    public static int? Map(PhysicalKey physical, Key fallback, bool mac)
    {
        var key = physical == PhysicalKey.None ? fallback : physical.ToQwertyKey();
        var android = key switch {
            >= Key.A and <= Key.Z => 29 + (int)key - (int)Key.A,
            >= Key.D0 and <= Key.D9 => 7 + (int)key - (int)Key.D0,
            >= Key.F1 and <= Key.F12 => 131 + (int)key - (int)Key.F1,
            >= Key.NumPad0 and <= Key.NumPad9 => 144 + (int)key - (int)Key.NumPad0,
            Key.Up => 19, Key.Down => 20, Key.Left => 21, Key.Right => 22,
            Key.LeftAlt => 57, Key.RightAlt => 58, Key.LeftShift => 59, Key.RightShift => 60,
            Key.Tab => 61, Key.Space => 62, Key.Enter => 66, Key.Back => 67,
            Key.Escape => 111, Key.Delete => 112, Key.LeftCtrl => 113, Key.RightCtrl => 114,
            Key.CapsLock => 115, Key.LWin => 117, Key.RWin => 118,
            Key.Home => 122, Key.End => 123, Key.Insert => 124, Key.PageUp => 92, Key.PageDown => 93,
            Key.OemComma => 55, Key.OemPeriod => 56, Key.OemTilde => 68, Key.OemMinus => 69,
            Key.OemPlus => 70, Key.OemOpenBrackets => 71, Key.OemCloseBrackets => 72,
            Key.OemPipe => 73, Key.OemSemicolon => 74, Key.OemQuotes => 75, Key.OemQuestion => 76,
            _ => -1
        };
        return (mac ? Mac : Windows).TryGetValue(android, out var native) ? native : null;
    }
}
